import json
from pathlib import Path
def F(label,value,state='Default'):return dict(kind='field',label=label,value=value,state=state)
def T(text,style='Body',color='muted'):return dict(kind='text',text=text,style=style,color=color)
def H(text):return dict(kind='heading',text=text)
def N(title,body='',tone='Brand',icon='shield-check'):return dict(kind='notice',title=title,body=body,tone=tone,icon=icon)
def R(title,sub='',to=None,right=None):return dict(kind='row',title=title,sub=sub,to=to,right=right)
def C(title,sub,hint,to='M14'):return dict(kind='contact',title=title,sub=sub,hint=hint,to=to)
def K(label,value):return dict(kind='kv',label=label,value=value)
def CK(label,selected=True,to=None):return dict(kind='check',label=label,selected=selected,to=to)
def B(label,to,secondary=False):return dict(kind='button',label=label,to=to,secondary=secondary)
def A(label,to,secondary=False):return dict(label=label,to=to,secondary=secondary)
def P(title,sub,value='+',to='M20'):return dict(kind='product',title=title,sub=sub,value=value,to=to)
def S(label,tone='Brand'):return dict(kind='status',label=label,tone=tone)
def tabs(*items):return dict(kind='tabs',items=items)
def hero(title,body,icon='shield-check',bg='navy'):return dict(kind='hero',title=title,body=body,icon=icon,bg=bg)
def search(text='Search by name or area'):return dict(kind='search',text=text)
def mp(title='Delhi · Assigned route',h=218):return dict(kind='map',title=title,h=h)
def met(*items):return dict(kind='metrics',items=items)
D=[]
def screen(id,title,blocks=None,actions=None,nav=None,back=None,**kwargs):
 d=dict(id=id,title=title,blocks=blocks or [],**kwargs)
 if actions:d['actions']=actions
 if nav:d['nav']=nav
 if back:d['back']=back
 D.append(d)

